TLM.f("Sancti/07-02",{"officium":"In Visitatione B. Mariæ Virginis","rule":["Gloria","Credo","Prefatio=Maria=Visitatióne;"],"ruleInherited":["Gloria","Credo","Prefatio=Maria=Festivitate","Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C11","from":{"GradualeP":"Commune/C11","Tractus":"Commune/C11"},"sections":{"Introitus":[{"k":"rubric","la":"Sedulius"},{"k":"text","la":"Salve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum."},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Salve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum."}],"Oratio":[{"k":"text","la":"Fámulis tuis, quǽsumus, Dómine, cœléstis grátiæ munus impertíre: ut, quibus beátæ Vírginis partus éxstitit salútis exórdium; Visitatiónis ejus votíva sollémnitas, pacis tríbuat increméntum."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Cant 2:8-14"},{"k":"text","la":"Ecce, iste venit sáliens in móntibus, transíliens colles; símilis est diléctus meus cápreæ hinnulóque cervórum. En, ipse stat post paríetem nostrum, respíciens per fenéstras, prospíciens per cancéllos. En, diléctus meus lóquitur mihi: Surge, própera, amíca mea, colúmba mea, formósa mea, et veni. Jam enim hiems tránsiit, imber ábiit et recéssit. Flores apparuérunt in terra nostra, tempus putatiónis advénit: vox túrturis audíta est in terra nostra: ficus prótulit grossos suos: víneæ floréntes dedérunt odórem suum. Surge, amíca mea, speciósa mea, et veni: colúmba mea in foramínibus petra, in cavérna macériæ, osténde mihi fáciem tuam, sonet vox tua in áuribus meis: vox enim tua dulcis et fácies tua decóra."}],"Graduale":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénta es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Felix es, sacra Virgo María, et omni laude digníssima: quia ex te ortus est sol justítiæ, Christus, Deus noster. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis"},{"k":"ref","la":"Luke 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénia es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo.","mark":"V"},{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 1:39-47"},{"k":"text","la":"In illo témpore: Exsúrgens María ábiit in montána cum festinatióne in civitátem Juda: et intrávit in domum Zacharíæ et salutávit Elísabeth. Et factum est, ut audivit salutatiónem Maríæ Elísabeth, exsultávit infans in útero ejus: et repléta est Spíritu Sancto Elísabeth, et exclamávit voce magna et dixit: Benedícta tu inter mulíeres, et benedíctus fructus ventris tui. Et unde hoc mihi, ut véniat Mater Dómini mei ad me? Ecce enim, ut facta est vox salutatiónis tuæ in áuribus meis, exsultávit in gáudio infans in útero meo. Et beáta, quæ credidísti, quóniam perficiéntur ea, quæ dicta sunt tibi a Dómino. Et ait María: Magníficat ánima mea Dóminum: et exsultávit spíritus meus in Deo, salutári meo."}],"Offertorium":[{"k":"text","la":"Beáta es, Virgo María, quæ ómnium portásti Creatórem: genuísti qui te fecit, et in ætérnum pérmanes Virgo."}],"Secreta":[{"k":"text","la":"Unigéniti tui, Dómine, nobis succúrrat humánitas: ut, qui, natus de Vírgine, Matris integritátem non mínuit, sed sacrávit; in Visitatiónis ejus sollémniis, nostris nos piáculis éxuens, oblatiónem nostram tibi fáciat accéptam Jesus Christus, Dóminus noster:"},{"k":"macro","name":"Qui tecum"}],"Communio":[{"k":"text","la":"Beáta víscera Maríæ Vírginis, quæ portavérunt ætérni Patris Fílium."}],"Postcommunio":[{"k":"text","la":"Súmpsimus, Dómine, celebritátis ánnuæ votíva sacraménta: præsta, quǽsumus; ut et temporális vitæ nobis remédia prǽbeant et ætérnæ."},{"k":"macro","name":"Per Dominum"}]},"hr":{"8f0eae79d2d2c5a4":{"t":"Sedulije, Ps 44, 2\n(Sedulije) Zdravo, sveta Majko, koja si nam porodila Kralja koji vlada nebom i zemljom u vjekovječne vjekove! (Ps 44, 2) Iz srca mi navire radosna riječ, pripovijedam svoja djela Kralju!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sedulije) Zdravo, sveta Majko, koja si nam porodila Kralja koji vlada nebom i zemljom u vjekovječne vjekove!","kn":"Zdravo, sveta Majko, što nam porodi Kralja, koji vlada nebom i zemljom u vjekovječne vjekove! (Ps. 44, 2) Iz mog srca izvire divna pjesma: djela su moja namijenjena Kralju. Slava Ocu. Zdravo.","knRef":"Kniewald 1942, str. 836–837 (snimka 419) (OCR)"},"26f85529fe1c0ff2":{"t":"<i>Pomolimo se</i>.\nUdijeli, Gospodine, svojim slugama dar nebeske milosti, da zavjetni blagdan pohođenja blažene Djevice dade porast mira onima kojima je njezin porod postao početkom spasenja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, udijeli slugama svojim dar nebeske milosti, da nama. kojima je porod bi. Djevice bio početak spasenja, zavjetni blagdan njezina pohoda podade porast mira. Po Gospodinu ...","knRef":"Kniewald 1942, str. 624–625 (snimka 313) (OCR)"},"41ea731de1be38bb":{"t":"Pj 2, 8-14\nČitanje knjige Mudrosti. Moj ljubljeni dolazi, sličan kozliću i janjetu, koje preskače bregove i skače po visinama. Gleda kroz otvor iza naše ograde i promatra kroz rešetke. Moj mi ljubljeni govori: Ustani, požuri se, prijateljice moja. golubice moja, ljepotice moja, i dođi! Zima prođe, kiša presta, nestade je, pojavi se cvijeće po našoj zemlji, vrijeme je pjevanja došlo. Glas grlice odjeknuo je našim livadama, smokva je urodila svojim plodom, procvali su vinogradi proširili svoj miris. Ustani, prijateljice moja, ljepotice moja, i dođi! Golubice moja, koja se kriješ u pukotinama pećina i skrovištima zidina, pokaži mi svoje lice, da u mojim ušima odjekne tvoj glas. Tvoj mi je glas sladak, i tvoje lice krasno!","kn":"Čitanje knjige Mudrosti (Pjesma nad pjesmama 2, 8-14). Evo moj ljubljeni,* koji dolazi, sličan je kozliću i lanetu, koje skače po gorama i preskače bregove. On iza naše ograde gleda kroz prozor, promatra kioz rešetke. Ljubljeni mi moj govori: Ustani, požuri se, prijateljice moja,® golubice moja, ljepotice moja i dođi! Jer zima već prođe, kiša presta i nestade je. Pokazalo se cvijeće po našoj zemlji, došlo je doba berbe. Glas je grlice odjeknuo po našim poljima, smokva je urodila svojim plodom, cvatući su vinogradi proširili svoj miris. Ustani, prijateljice moja, ljepotice moja i dođi! Golubice moja, koja se kriješ u pukotinama pećina i skrovištima zidova, pokaži mi svoje lice, da odjekne tvoj glas u mojim ušima. Jer tvoj je glas sladak i tvoje lice krasno.","knRef":"Kniewald 1942, str. 624–625 (snimka 313) (OCR)"},"a78ab01cf59234e0":{"t":"Blagoslovljena si i časna, Djevo Marijo, koja si bez povrede djevičanstva bila majka Spasiteljeva. Bogorodice Djevo, u tvojem se zatvori krilu postavši čovjek, onaj koga sav svijet ne može obuhvatiti.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nSretna si, sveta Djevo Marijo, i svake si hvale predostojna, jer je iz tebe isteklo Sunce pravde, Krist Bog naš, <i>aleluja</i>.","v":"∅ → aleluia aleluia; ∅ → aleluia","kn":", Blagcislovema si i časna. Djevo Marlj'O, koja se bez povrede čistoće nađe mati Spasiteljeva. Bogorodice Djevo u tvojem se, postavši čovj.ek, zatvori krilu, koga sav svijet ne obuhvata. Aleluja, aleluja. Blažena si, sveta Djevice Marijo, i predoistojna svake hvale, jer se iz tebe rodi sunce pravde, Krist, Bog naš. Aleluja.","knRef":"Kniewald 1942, str. 700–701 (snimka 351) (OCR)"},"3677f7a70c26e6e3":{"t":"Lk 1, 39-47\nSlijedi sveto Evanđelje po Luki. U ono vrijeme Marija žurno pođe u planinski kraj u grad Judin, uđe u kuću Zaharije i pozdravi Elizabetu. Kad je Elizabeta čula Marijin pozdrav, zaigra dijete pod njezinim srcem, pa nadahnuta Duhom Svetim klikne jakim glasom: Blagoslovljena ti među ženama, i blagoslovljen plod utrobe tvoje! Tko sam ja da majka mojega Gospodina dolazi k meni? I eto. čim sam čula tvoj pozdrav, od radosti dijete zaigra u meni. Blago tebi, jer si povjerovala, da će se ispuniti što ti je rekao Gospodin. Marija na to reče: Veliča duša moja Gospodina i raduje se duh moj u Bogu spasu mojemu!","kn":"t Slijedi sv. evanđelje po Luki (1, 39-47). U ono vrijeme ustade Marija i pođe žurno u gore, u grad Judin. Uđe u Zaharijinu kuću i pozdravi Elizabetu. Kad je Elizabeta čula Marijin pozdrav, zaigra dijete u njoj. I napuni se Elizabeta duha Svetoga i usklikne jakim glasom: Blagoslovljena ti među ženama i blagoslovljen plod utrobe tvoje! Otkuda meni to, da k meni dolazi majka mojega Gospodina? Jer evO', čim sam čula tvoj pozdrav, zaigralo je dijele u meni. Blago tebi, što si vjerovala, jer će se ispuniti, što ti je rekao Gospodin. Marija nato Kvairena subota u doSašfu reče: Neka veliča moja duša Gospodina, i raduje se moj duh u Bogu, mojemu Spasitelju.","knRef":"Kniewald 1942, str. 44–45 (snimka 23) (OCR)"},"6356ff1e5bf54d76":{"t":"Blažena si, Djevice Marijo, koja si nosila Stvoritelja svega; porodila si onoga koji te je stvorio i dovijeka ostaješ Djevica.","v":"aleluia → ∅","kn":"Blažena si, Djevice Marijo, koja si nosila Stvoritelja svega, rodila si onoga, koji je Tebe stvorioi 1 dovijeka ostaješ djevicom.","knRef":"Kniewald 1942, str. 678–679 (snimka 340) (OCR)"},"11d8526ff78ed924":{"t":"Pomoglo nam, Gospodine, čovječanstvo tvojega Jedinorođenoga, koji rodivši se od Djevice materinog djevičanstva nije umanjio, nego ga je posvetio; da nas o blagdanu njezina pohođenja oslobodi od naših krivica i naš prinos učini tebi prijatnim, Isus Krist, Gospodin naš.\n<i>Koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Priteklo nam. Gospodine, čovječanstvo Tvoga Jedinca, koji rodivši se od Djevice nije umanjio majčine netaknutosti, nego je posvetio, te nas o slavi njezina pohoda izbavio iz naših nečistoća, a prinos naš Tebi učinio prijatnim Isus Krist, Gospodin naš, koji s Tobom ...","knRef":"Kniewald 1942, str. 626–627 (snimka 314) (OCR)"},"cf1ad2e66b2e9e92":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: i da te <i> o pohođenju</i> blažene Marije vazda Djevice hvalimo, blagoslivljamo i slavimo. Ona je osjenjena Duhom Svetim začela jedinorođenoga Sina tvoga i sačuvavši slavu djevičanstva prosula svijetom vječno svjetlo Isusa Krista Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, da uvijek i, svagdje Tebi, Gospodine sveti. Oče svemogući, vječni Bože, zahvaljujemo i da Te hvalimo, slavimo i uzvisujemo o (Pohodu, Prikazanju, Bezgrješnom Začeću, Navještenju, Uznesenju. Rođenju, svetkovini) blažene Marije, vazda Djevice, koja je po Duhu Svetom začela jedinorođenoga Tvoga Sina i zadržavši slavu djevičanstva dala svijetu vječno svijetlo, Isuisa Krista, Gospodina našega, po kome anđeli hvale Tvoje veličanstvo, klanjaju Ti se gospodstva, podlažu Ti se vlasti, slave Te nebesa i nebeske sile s blaženim Serafinima kličući u zajedničkoj^ radosti. A mi Te molimo, da nam zapovjediš s njima sjediniti naše glasove smjerno ispovijedajući:","knRef":"Kniewald 1942, str. 22–23 (snimka 12) (OCR)"},"4cc414b9b992a40d":{"t":"Blaženo tijelo Marije Djevice koje je nosilo Sina vječnoga Oca.","kn":"Blaženokrilo Djevice Marije, koje je nosilo Sina vječnoga Oca,","knRef":"Kniewald 1942, str. 838–839 (snimka 420) (OCR)"},"150f57ef8d5d33a5":{"t":"<i>Pomolimo se</i>.\nPrimivši, Gospodine, zavjetna otajstva godišnje svečanosti, molimo te, da nam udijele okrepu i za vremeniti i za vječni život.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primivši, Gospodine, zavjetna otajstva godišnje svetkovine, molimo Te, da nam ndijele okrepo i za vremeniti i za vječni život, po G. n.","knRef":"Kniewald 1942, str. 702–703 (snimka 352) (OCR)"}},"variants":{"paschal":{"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis."},{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}]}}});
